	private void Awake()
	{
		actionNameRectTransform = actionNameText.GetComponent<RectTransform>();
	}

	public void InitializeFirstAction(ActionFace actionFace, string instanceTypeString, bool addTimelessTag, Dice dice, bool forgeDiceFace)
	{
		if (instanceTypeString != string.Empty)
		{
			ToggleInstanceTypeText(value: true, instanceTypeString);
		}
		else
		{
			ToggleInstanceTypeText(value: false);
		}
		InitializeActionDescription(actionFace.BattleAction, actionFace.ModifiedActionValue, actionFace.ActionValue, actionNameText, actionDescriptionText, addTimelessTag, null, dice, forgeDiceFace);
		SetAlphaToZero();
	}

	private void ToggleInstanceTypeText(bool value, string text = "")
	{
		headerGameObject.SetActive(value);
		instanceTypeTextHolderGameObject.SetActive(value);
		if (value)
		{
			instanceTypeText.SetText(text);
			LayoutRebuilder.ForceRebuildLayoutImmediate(instanceTypeText.rectTransform);
		}
	}

	private void InitializeActionDescription(BattleAction battleAction, int modifiedActionAmount, int actionAmount, TextMeshProUGUI nameText, TextMeshProUGUI descriptionText, bool addTimelessTag, DiceFace diceFace, Dice dice, bool forgeDiceFace = false)
	{
		if (!battleAction.BattleActionSprite)
		{
			actionSprite.sprite = battleAction.BaseBattleActionData.ActionSprite;
		}
		else
		{
			actionSprite.sprite = battleAction.BattleActionSprite;
		}
		ToggleActionSprite(value: true);
		actionDescriptionText.gameObject.SetActive(value: true);
		BaseBattleActionData baseBattleActionData = battleAction.BaseBattleActionData;
		if (baseBattleActionData.ApplyColorToActionIcon)
		{
			if (baseBattleActionData.EnableColorReference)
			{
				actionSprite.color = baseBattleActionData.colorReference.Value;
			}
			else
			{
				actionSprite.color = baseBattleActionData.ActionColor;
			}
		}
		else
		{
			actionSprite.color = Color.white;
		}
		nameText.SetText(GetTintedDescriptionPurifyCorrupt(battleAction.GetActionName()));
		AdjustNameTextSize(nameText);
		int bonusAmount = modifiedActionAmount - actionAmount;
		string actionDescription = baseBattleActionData.GetActionDescription(actionAmount, bonusAmount, battleAction, addTimelessTag, dice, diceFace, noRefreshedActionDescription: false, forgeDiceFace);
		Action action = delegate
		{
			if (baseBattleActionData.ActionFaceForDescriptions.Length != 0)
			{
				for (int i = 0; i < baseBattleActionData.ActionFaceForDescriptions.Length; i++)
				{
					actionDescription = GetTintedDescriptionWithBattleActionAsTag(actionDescription, baseBattleActionData.ActionFaceForDescriptions[i].BattleAction);
				}
			}
		};
		Action action2 = delegate
		{
			actionDescription = GetTintedDescriptionWithTags(actionDescription, baseBattleActionData.Effects, baseBattleActionData.GetTags(addTimelessTag: true, null, battleAction));
		};
		if (baseBattleActionData.TintEffectsAndTagsBeforeActionFaceForDescriptions)
		{
			action2();
			action();
		}
		else
		{
			action();
			action2();
		}
		actionDescription = GetTintedDescriptionPurifyCorrupt(actionDescription);
		descriptionText.SetText(actionDescription);
	}

	public void InitializeOnlyNameActionDescriptionPanel(NodeViewData nodeViewData)
	{
		ToggleInstanceTypeText(value: false);
		ToggleActionSprite(value: false);
		actionNameText.SetText(nodeViewData.ButtonName);
		AdjustNameTextSize(actionNameText);
		actionDescriptionText.gameObject.SetActive(value: false);
		SetAlphaToZero();
	}

	public void DisableActionDescriptionPanelDescription()
	{
		actionDescriptionText.gameObject.SetActive(value: false);
	}

	private void AdjustNameTextSize(TextMeshProUGUI nameText, bool ignoreNameLineBreakCheck = false)
	{
		nameText.enableAutoSizing = false;
		if (!ignoreNameLineBreakCheck && !LanguagesIndexes.IsIgnoreLineBreakOnEffectFeedback())
		{
			string[] array = nameText.text.Split(' ');
			List<int> list = new List<int>();
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].Length < 3)
				{
					list.Add(i);
				}
			}
			if (list.Count == 1 && list.First() == array.Length - 1)
			{
				string text = "";
				string localizedSpace = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace();
				for (int j = 0; j < array.Length; j++)
				{
					text = ((j != array.Length - 1) ? ((j != array.Length - 2) ? (text + array[j] + "\n") : (text + array[j] + localizedSpace)) : (text + array[j]));
				}
				nameText.SetText(text);
			}
		}
		InvokeAlternatives.InvokeAfterFrame(this, delegate
		{
			float num = 0f;
			num = ((nameText.textInfo.lineCount == 4) ? 190f : ((nameText.textInfo.lineCount == 3) ? 150f : ((nameText.textInfo.lineCount != 2) ? 80f : 110f)));
			RectTransform rectTransform = nameText.rectTransform;
			rectTransform.sizeDelta = new Vector2(rectTransform.sizeDelta.x, num);
			nameText.enableAutoSizing = true;
			LayoutRebuilder.ForceRebuildLayoutImmediate(nameText.rectTransform);
		});
	}

	private void ToggleActionSprite(bool value)
	{
		actionSpriteHolder.SetActive(value);
		if (!tagDescriptionInstance)
		{
			actionNameRectTransform.sizeDelta = new Vector2(value ? actionNameTextXSizeWithIcon : actionNameTextXSizeWithoutIcon, actionNameRectTransform.sizeDelta.y);
		}
	}

	private string GetTintedDescriptionWithTags(string description, Effect[] effects, Tag[] tags, bool tintWholeWordOnlyGerman = false)
	{
		return tintWordHandler.GetTintedDescriptionWithTags(description, effects, tags, tintWholeWordOnlyGerman);
	}

	public string GetTintedDescriptionPurifyCorrupt(string description)
	{
		return tintWordHandler.GetTintedDescriptionPurifyCorrupt(description);
	}

	private string GetTintedDescriptionWithBattleActionAsTag(string description, BattleAction battleAction)
	{
		return tintWordHandler.GetTintedDescription(description, battleAction.GetActionName());
	}

	public void InitializeSecondAction(ActionFace actionFace, Dice dice)
	{
		bool addTimelessTag = true;
		if (actionFace is DiceFace && (actionFace as DiceFace).Timeless)
		{
			addTimelessTag = false;
		}
		InitializeActionDescription(actionFace.SecondBattleAction, actionFace.SecondModifiedActionValue, actionFace.SecondActionValue, actionNameText, actionDescriptionText, addTimelessTag, actionFace as DiceFace, dice);
	}

	public void UpdateEffectDescriptionText(EffectInstance effectInstance, GameObject effectOwner)
	{
		ToggleInstanceTypeText(value: false);
		Effect effect = effectInstance.Effect;
		actionSprite.sprite = effect.EffectSprite;
		ToggleActionSprite(value: true);
		actionNameText.SetText(GetTintedDescriptionPurifyCorrupt(effect.GetEffectName()));
		AdjustNameTextSize(actionNameText);
		string effectDescription = effect.GetEffectDescription(effectInstance.EffectAmount, effectOwner);
		effectDescription = GetTintedDescriptionWithTags(effectDescription, effect.ExtraEffects, effect.Tags);
		if (effect.ActionFaceForDescriptions.Length != 0)
		{
			for (int i = 0; i < effect.ActionFaceForDescriptions.Length; i++)
			{
				effectDescription = GetTintedDescriptionWithBattleActionAsTag(effectDescription, effect.ActionFaceForDescriptions[i].BattleAction);
			}
		}
		effectDescription = GetTintedDescriptionPurifyCorrupt(effectDescription);
		actionDescriptionText.SetText(effectDescription);
		SetAlphaToZero();
	}

	public void UpdateEffectDescriptionText(Effect effect)
	{
		actionSprite.sprite = effect.EffectSprite;
		ToggleActionSprite(value: true);
		actionNameText.SetText(GetTintedDescriptionPurifyCorrupt(effect.GetEffectName()));
		AdjustNameTextSize(actionNameText);
		string description = effect.GetEffectDescription(EffectsValues.NO_VALUE);
		string tintedDescriptionWithTags = GetTintedDescriptionWithTags(description, effect.ExtraEffects, effect.Tags);
		if (effect.ActionFaceForDescriptions.Length != 0)
		{
			for (int i = 0; i < effect.ActionFaceForDescriptions.Length; i++)
			{
				description = GetTintedDescriptionWithBattleActionAsTag(description, effect.ActionFaceForDescriptions[i].BattleAction);
			}
		}
		actionDescriptionText.SetText(GetTintedDescriptionPurifyCorrupt(tintedDescriptionWithTags));
	}

	public void UpdateTagDescriptionText(Tag tag)
	{
		if ((bool)tag.TagSprite)
		{
			actionSprite.sprite = tag.TagSprite;
			ToggleActionSprite(value: true);
		}
		else
		{
			ToggleActionSprite(value: false);
		}
		actionNameText.SetText(GetTintedDescriptionPurifyCorrupt(tag.GetTagName()));
		AdjustNameTextSize(actionNameText);
		actionDescriptionText.SetText(GetTintedDescriptionPurifyCorrupt(tag.GetTagDescription()));
	}

	public void UpdateBattleActionDescriptionAsTag(BattleAction battleAction, int amount)
	{
		if (!battleAction.BattleActionSprite)
		{
			actionSprite.sprite = battleAction.BaseBattleActionData.ActionSprite;
		}
		else
		{
			actionSprite.sprite = battleAction.BattleActionSprite;
		}
		actionNameText.SetText(GetTintedDescriptionPurifyCorrupt(string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("ActionTag"), battleAction.GetActionName())));
		AdjustNameTextSize(actionNameText);
		string text = "";
		if (battleAction.Timeless)
		{
			string text2 = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDotAtTheEndFormat(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("Timeless_N"));
			text = text + "\n" + text2;
		}
		actionDescriptionText.SetText(GetTintedDescriptionPurifyCorrupt(battleAction.BaseBattleActionData.GetActionDescription(amount, battleAction, noRefreshedActionDescription: false) + text));
	}

	public void UpdateStarAbilityDescriptionText(StarAbility starAbility)
	{
		actionSprite.sprite = starAbility.StarAbilitySprite;
		ToggleActionSprite(value: true);
		actionNameText.SetText(starAbility.GetLocalizedName(addActiveOrb: false));
		AdjustNameTextSize(actionNameText);
		actionDescriptionText.SetText(GetTintedDescriptionPurifyCorrupt(starAbility.GetLocalizedDescription()));
	}

	public void InitializeButtonDescription(ButtonDescriptionData buttonDescriptionData, int firstValue = -1)
	{
		if (!ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed)
		{
			if (buttonDescriptionData.CanShowButtonPrompt() && !buttonDescriptionData.HideJoystickKeyboardPrompt)
			{
				if (buttonDescriptionData.ButtonWithJoystickKeyboardPrompt)
				{
					joystickKeyboardGlyph.gameObject.SetActive(value: true);
					joystickKeyboardGlyph.InitializeExternal(buttonDescriptionData.ActionName);
					if (buttonDescriptionData.SecondButtonWithJoystickKeyboardPrompt)
					{
						secondJoystickKeyboardGlyph.gameObject.SetActive(value: true);
						LayoutRebuilder.ForceRebuildLayoutImmediate(secondJoystickKeyboardGlyphText);
						secondJoystickKeyboardGlyph.InitializeExternal(buttonDescriptionData.SecondActionName);
					}
					else
					{
						secondJoystickKeyboardGlyph.gameObject.SetActive(value: false);
					}
					LayoutRebuilder.ForceRebuildLayoutImmediate(joystickKeyboardGlyph.transform.parent.GetComponent<RectTransform>());
				}
			}
			else if (buttonDescriptionData.ButtonWithJoystickKeyboardPrompt)
			{
				joystickKeyboardGlyph.gameObject.SetActive(value: false);
				secondJoystickKeyboardGlyph.gameObject.SetActive(value: false);
			}
		}
		else if (buttonDescriptionData.ButtonWithJoystickKeyboardPrompt)
		{
			joystickKeyboardGlyph.gameObject.SetActive(value: false);
			secondJoystickKeyboardGlyph.gameObject.SetActive(value: false);
		}
		ToggleInstanceTypeText(value: false);
		ToggleActionSprite(value: false);
		actionDescriptionText.gameObject.SetActive(value: true);
		actionNameText.SetText(buttonDescriptionData.ButtonName);
		AdjustNameTextSize(actionNameText, buttonDescriptionData.IgnoreNameLineBreakCheck);
		if (buttonDescriptionData.ButtonWithJoystickKeyboardPrompt)
		{
			actionNameText.ForceMeshUpdate(ignoreActiveState: true);
			RectTransform component = actionNameText.GetComponent<RectTransform>();
			component.sizeDelta = new Vector2(actionNameText.GetRenderedValues(onlyVisibleCharacters: true).x, component.sizeDelta.y);
		}
		string text = buttonDescriptionData.ButtonDescription;
		if (firstValue > -1)
		{
			text = Smart.Format(text, firstValue);
		}
		text = GetTintedDescriptionWithTags(text, buttonDescriptionData.GetEffects(), buttonDescriptionData.Tags);
		text = buttonDescriptionData.GetAfterTintingLocalizedDescription(text);
		actionDescriptionText.SetText(GetTintedDescriptionPurifyCorrupt(text));
		SetAlphaToZero();
	}

	public void InitializeRunModifier(RunModifier runModifier)
	{
		ToggleInstanceTypeText(value: false);
		ToggleActionSprite(value: false);
		actionDescriptionText.gameObject.SetActive(value: true);
		actionNameText.SetText(runModifier.GetLocalizedName());
		AdjustNameTextSize(actionNameText);
		string description = GetTintedDescriptionWithTags(runModifier.GetLocalizedDescription(), runModifier.Effects, runModifier.Tags);
		for (int i = 0; i < runModifier.ActionFaceForDescriptions.Length; i++)
		{
			description = GetTintedDescriptionWithBattleActionAsTag(description, runModifier.ActionFaceForDescriptions[i].BattleAction);
		}
		actionDescriptionText.SetText(GetTintedDescriptionPurifyCorrupt(description));
		SetAlphaToZero();
	}

	public void InitializeOverCorruptedAction(OverCorruptionAction overCorruptionAction)
	{
		string localizedString = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("OverCorruption");
		ToggleInstanceTypeText(value: true, localizedString);
		InitializeActionDescription(overCorruptionAction.BattleAction, overCorruptionAction.ActionAmount, overCorruptionAction.ActionAmount, actionNameText, actionDescriptionText, addTimelessTag: false, null, null);
		SetAlphaToZero();
	}

	public void InitializeOmenDescription(OmenData omenData, OmenInstance omenInstance)
	{
		actionDescriptionText.gameObject.SetActive(value: true);
		ToggleInstanceTypeText(value: false);
		ToggleActionSprite(value: false);
		string text = "";
		string text2 = string.Format(arg1: omenData.OmenTier.EventTier ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(omenData.OmenTier.EventBlessingNameID) : ((!omenData.Character.CharacterEnum) ? omenData.Character.LocalizedCharacterName : ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedNeutral()), format: ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDiceTypeCharacterOwnerFormatt(), arg0: omenData.GetOmenName());
		string chapterAppearanceText = omenData.GetChapterAppearanceText();
		if (chapterAppearanceText != "")
		{
			text2 = string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDiceTypeCharacterOwnerFormatt(), text2, chapterAppearanceText);
		}
		actionNameText.SetText(text2);
		if (omenInstance != null && omenData.MuteForMod && omenInstance.Compendium)
		{
			TextMeshProUGUI textMeshProUGUI = actionNameText;
			textMeshProUGUI.text = textMeshProUGUI.text + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedMuted();
		}
		AdjustNameTextSize(actionNameText);
		string description = omenData.OmenConvertedDescription();
		if (omenData.EnableBattleAction)
		{
			BaseBattleActionData baseBattleActionData = omenData.BattleAction.BaseBattleActionData;
			if (omenData.EnableBattleActionAsTag)
			{
				if (omenData.TintBattleActionBeforeEffectsAndTags)
				{
					description = GetTintedDescriptionWithBattleActionAsTag(description, omenData.BattleAction);
					description = GetTintedDescriptionWithTags(description, baseBattleActionData.Effects, baseBattleActionData.GetTags(addTimelessTag: false), omenData.TintWholeWordOnlyGerman);
				}
				else
				{
					description = GetTintedDescriptionWithTags(description, baseBattleActionData.Effects, baseBattleActionData.GetTags(addTimelessTag: false), omenData.TintWholeWordOnlyGerman);
					description = GetTintedDescriptionWithBattleActionAsTag(description, omenData.BattleAction);
				}
			}
			else
			{
				description = GetTintedDescriptionWithTags(description, baseBattleActionData.Effects, baseBattleActionData.GetTags(addTimelessTag: false), omenData.TintWholeWordOnlyGerman);
			}
		}
		description = GetTintedDescriptionWithTags(description, omenData.Effects, omenData.Tags, omenData.TintWholeWordOnlyGerman);
		for (int i = 0; i < omenData.ActionFaceForDescriptions.Length; i++)
		{
			description = GetTintedDescriptionWithBattleActionAsTag(description, omenData.ActionFaceForDescriptions[i].BattleAction);
		}
		if (omenData is GainSomethingWithDrawBackOmenData)
		{
			GainSomethingWithDrawBackOmenData obj = omenData as GainSomethingWithDrawBackOmenData;
			BaseBattleActionData baseBattleActionData2 = obj.GoodEffectAction.BaseBattleActionData;
			BaseBattleActionData baseBattleActionData3 = obj.BadEffectAction.BaseBattleActionData;
			description = GetTintedDescriptionWithTags(description, baseBattleActionData2.Effects, baseBattleActionData2.GetTags(addTimelessTag: false), omenData.TintWholeWordOnlyGerman);
			description = GetTintedDescriptionWithTags(description, baseBattleActionData3.Effects, baseBattleActionData3.GetTags(addTimelessTag: false), omenData.TintWholeWordOnlyGerman);
		}
		actionDescriptionText.SetText(GetTintedDescriptionPurifyCorrupt(description));
		SetAlphaToZero();
	}

	public void InitializeStarAbility(StarAbility starAbility)
	{
		ToggleInstanceTypeText(value: false);
		ToggleActionSprite(value: false);
		actionNameText.SetText(starAbility.GetLocalizedName(addActiveOrb: true));
		AdjustNameTextSize(actionNameText);
		string tintedDescriptionWithTags = GetTintedDescriptionWithTags(starAbility.GetLocalizedDescription(), starAbility.Effects, starAbility.Tags);
		actionDescriptionText.SetText(GetTintedDescriptionPurifyCorrupt(tintedDescriptionWithTags));
		SetAlphaToZero();
	}

	[Button(null)]
	public void SetAlphaToZero()
	{
		if (noAnimation)
		{
			base.gameObject.SetActive(value: false);
		}
		else if (enableCanvasGroup)
		{
			canvasGroup.alpha = 0f;
			base.gameObject.SetActive(value: true);
			if (enableActionDescriptionInstanceExtraTags)
			{
				actionDescriptionInstanceExtraTags.SetAlphaToZero();
			}
			if (enableDieFacesPanel)
			{
				dieFacesPanel.GetComponent<CanvasGroup>().alpha = 0f;
			}
		}
	}

	[Button(null)]
	public void SetAlphaToOne()
	{
		if (noAnimation)
		{
			base.gameObject.SetActive(value: true);
		}
		else if (enableCanvasGroup)
		{
			canvasGroup.alpha = 1f;
			base.gameObject.SetActive(value: true);
			if (enableActionDescriptionInstanceExtraTags)
			{
				actionDescriptionInstanceExtraTags.SetAlphaToOne();
			}
			if (enableDieFacesPanel)
			{
				dieFacesPanel.GetComponent<CanvasGroup>().alpha = 1f;
			}
		}
	}

	public void Fade(bool fadeIn)
	{
		if (noAnimation)
		{
			base.gameObject.SetActive(fadeIn);
		}
		else if (enableCanvasGroup && base.gameObject.activeInHierarchy)
		{
			int num = (fadeIn ? 1 : 0);
			StartCoroutine(canvasGroup.FadeCanvasGroupCoroutine(fadeDuration, num, fadeCurve, isRealtime: true));
			if (enableActionDescriptionInstanceExtraTags)
			{
				actionDescriptionInstanceExtraTags.Fade(fadeIn);
			}
			if (enableDieFacesPanel)
			{
				StartCoroutine(dieFacesPanel.GetComponent<CanvasGroup>().FadeCanvasGroupCoroutine(fadeDuration, num, fadeCurve, isRealtime: true));
			}
		}
	}
}
